require_once dirname(__DIR__,5).'/wp-load.php';
function dAssert(bool $c,string $m):void{if(!$c)throw new RuntimeException($m);}
function dTimestamp(string $value,string $label):void{dAssert(preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/D',$value)===1,"Timestamp inválido: {$label}");}
function dRequest(string $method,string $path,array $body=[]):WP_REST_Response{$parts=wp_parse_url($path);$r=new WP_REST_Request($method,'/veciahorra/v1/'.ltrim((string)($parts['path']??''),'/'));if(isset($parts['query'])){parse_str((string)$parts['query'],$q);$r->set_query_params($q);}if($body!==[]){$r->set_header('Content-Type','application/json');$r->set_body((string)wp_json_encode($body));}return rest_do_request($r);}
global $wpdb;$p=$wpdb->prefix.Config::TABLE_PREFIX;do_action('rest_api_init');
$imageManifest=require dirname(__DIR__).'/fixtures/training-demo/image-manifest.php';
$categoryManifest=require dirname(__DIR__).'/fixtures/training-demo/category-manifest.php';
dAssert(count($imageManifest)===20,'Manifest de imágenes debe contener 20 entradas.');
dAssert(count($categoryManifest)===8,'Manifest de categorías debe contener 8 entradas.');
$assetKeys=array_column($imageManifest,'asset_key');$paths=array_column($imageManifest,'relative_path');
dAssert(count(array_unique(array_keys($imageManifest)))===20,'Product keys duplicadas.');
dAssert(count(array_unique($assetKeys))===20,'Asset keys duplicadas.');
dAssert(count(array_unique($paths))===20,'Paths de imagen duplicados.');
$login=['va_demo_carolina'=>'VA-Cliente-2026!','va_demo_minimarket_vecinos'=>'VA-Vecinos-2026!','va_demo_minimarket_central'=>'VA-Central-2026!','va_demo_minimarket_plaza'=>'VA-Plaza-2026!','va_demo_diego'=>'VA-Diego-2026!','va_demo_jose'=>'VA-Jose-2026!','va_demo_carolina_rojas'=>'VA-Carolina-2026!','va_demo_luis'=>'VA-Luis-2026!','va_demo_daniela'=>'VA-Daniela-2026!','va_demo_pedro'=>'VA-Pedro-2026!','va_demo_camila'=>'VA-Camila-2026!'];
foreach($login as $username=>$password)dAssert(wp_authenticate($username,$password) instanceof WP_User,"Login falló: {$username}");
$customer=get_user_by('login','va_demo_carolina');dAssert($customer instanceof WP_User,'Cliente ausente.');wp_set_current_user($customer->ID);
$categoryIds=[];foreach($categoryManifest as $key=>$entry){$term=get_term_by('slug',$entry['slug'],$entry['taxonomy']);dAssert($term instanceof WP_Term,"Categoría training ausente: {$key}");dAssert($term->name===$entry['name']&&(int)$term->parent===0&&(string)$term->description==='',"Categoría training incompatible: {$key}");$categoryIds[$key]=(int)$term->term_id;}
$expectedProductCategories=['coca-cola-original-15-l'=>'vecised','coca-cola-zero-15-l'=>'vecised','cachantun-sin-gas-15-l'=>'vecised','leche-colun-entera-1-l'=>'vecifrio','yogurt-soprole'=>'vecifrio','mantequilla-colun'=>'vecifrio','arroz-tucapel-1-kg'=>'despensa','tallarines-carozzi-400-g'=>'despensa','salsa-tomates-carozzi'=>'despensa','aceite-chef-1-l'=>'despensa','super-8'=>'antojo','galletas-triton'=>'antojo','papas-fritas-marco-polo'=>'antojo','lavalozas-quix'=>'limpieza','detergente-omo'=>'limpieza','papel-higienico-elite'=>'limpieza','queso-laminado'=>'picoteo','jamon-pierna'=>'picoteo','pan-de-molde-ideal'=>'horno','platano'=>'feria'];
$demoProducts=$wpdb->get_results("SELECT id,slug,sku,image_id,category_id FROM {$p}products WHERE sku LIKE 'DEMO-%' AND status='active' ORDER BY id",ARRAY_A);dAssert(count($demoProducts)===20,'Productos demo activos incompletos.');
foreach($demoProducts as $product){$expectedKey=$expectedProductCategories[$product['slug']]??null;dAssert(is_string($expectedKey)&&(int)$product['category_id']===$categoryIds[$expectedKey],"Categoría de producto inválida: {$product['slug']}");}
foreach($demoProducts as $product){$entry=$imageManifest[$product['slug']]??null;dAssert(is_array($entry),"Manifest ausente: {$product['slug']}");$imageId=(int)($product['image_id']??0);dAssert($imageId>0,"Imagen demo ausente: {$product['slug']}");$attachment=get_post($imageId);dAssert($attachment instanceof WP_Post&&$attachment->post_type==='attachment'&&str_starts_with((string)$attachment->post_mime_type,'image/'),"Attachment demo inválido: {$product['slug']}");dAssert(get_post_meta($imageId,'_veciahorra_demo_asset',true)===$entry['asset_key'],"Asset key inválida: {$product['slug']}");$metadata=wp_get_attachment_metadata($imageId);dAssert(is_array($metadata)&&!empty($metadata['file']),"Metadata de imagen demo inválida: {$product['slug']}");$url=wp_get_attachment_image_url($imageId,'medium');dAssert(is_string($url)&&$url!=="","URL de imagen demo inválida: {$product['slug']}");$file=get_attached_file($imageId);dAssert(is_string($file)&&$file!==''&&is_file($file),"Archivo de imagen demo ausente: {$product['slug']}");dAssert(hash_equals($entry['sha256'],(string)hash_file('sha256',$file)),"SHA-256 runtime inválido: {$product['slug']}");}
$temporalRows=[...$wpdb->get_results("SELECT CONCAT('product:',slug) label,created_at,updated_at,NULL approved_at,NULL submitted_at,NULL published_at FROM {$p}products WHERE sku LIKE 'DEMO-%'",ARRAY_A),...$wpdb->get_results("SELECT CONCAT('inventory:',i.id) label,i.created_at,i.updated_at,NULL approved_at,NULL submitted_at,NULL published_at FROM {$p}inventory i JOIN {$p}products p ON p.id=i.product_id WHERE p.sku LIKE 'DEMO-%'",ARRAY_A),...$wpdb->get_results("SELECT CONCAT('store:',id) label,created_at,updated_at,approved_at,NULL submitted_at,NULL published_at FROM {$p}stores WHERE business_name IN ('Minimarket Los Vecinos','Minimarket Central','Minimarket Plaza Sur')",ARRAY_A),...$wpdb->get_results("SELECT CONCAT('courier:',id) label,created_at,updated_at,approved_at,NULL submitted_at,NULL published_at FROM {$p}couriers WHERE display_name='Diego Morales'",ARRAY_A),...$wpdb->get_results("SELECT CONCAT('provider:',id) label,created_at,updated_at,approved_at,submitted_at,published_at FROM {$p}service_providers WHERE email LIKE 'va_demo_%@veciahorra.test'",ARRAY_A)];
foreach($temporalRows as $row){foreach(['created_at','updated_at'] as $field)dTimestamp((string)$row[$field],"{$row['label']}.{$field}");dAssert($row['created_at']<=$row['updated_at'],"Orden temporal inválido: {$row['label']}");foreach(['approved_at','submitted_at','published_at'] as $field)if($row[$field]!==null)dTimestamp((string)$row[$field],"{$row['label']}.{$field}");}
$official=['coca-cola-original-15-l','tallarines-carozzi-400-g','salsa-tomates-carozzi','super-8'];$store=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM {$p}stores WHERE business_name=%s",'Minimarket Los Vecinos'));$added=[];
try{
 foreach($official as $slug){$row=$wpdb->get_row($wpdb->prepare("SELECT i.id,i.stock,i.status,p.status product_status FROM {$p}inventory i JOIN {$p}products p ON p.id=i.product_id WHERE p.slug=%s AND i.minimarket_id=%d",$slug,$store),ARRAY_A);dAssert($row!==null&&(int)$row['stock']>=4&&$row['status']==='active'&&$row['product_status']==='active',"Oferta oficial inválida: {$slug}");$response=dRequest('POST','cart/items',['inventory_id'=>(int)$row['id'],'quantity'=>1]);dAssert(in_array($response->get_status(),[200,201],true),"No se agregó al carrito: {$slug}");$added[]=$slug;}
 $cart=dRequest('GET','cart')->get_data()['data'];dAssert(count($cart)>=4,'Carrito oficial incompleto.');
 foreach(['va_demo_minimarket_vecinos','va_demo_minimarket_central','va_demo_minimarket_plaza'] as $username){$u=get_user_by('login',$username);wp_set_current_user($u->ID);dAssert(current_user_can(MinimarketRole::CAPABILITY),'Capability Minimarket ausente.');$me=dRequest('GET','minimarket/me');dAssert($me->get_status()===200,'Panel Minimarket no accesible.');}
 $central=get_user_by('login','va_demo_minimarket_central');wp_set_current_user($central->ID);$centralRows=dRequest('GET','minimarket/inventory')->get_data()['data'];$centralStore=(int)get_user_meta($central->ID,MinimarketRole::STORE_META_KEY,true);dAssert(count($centralRows)===12,'Inventario Central incorrecto.');foreach($centralRows as $row)dAssert((int)$wpdb->get_var($wpdb->prepare("SELECT minimarket_id FROM {$p}inventory WHERE id=%d",(int)$row['inventory_id']))===$centralStore,'Central vio inventario ajeno.');
 $courier=get_user_by('login','va_demo_diego');wp_set_current_user($courier->ID);dAssert(current_user_can(CourierRole::CAPABILITY)&&dRequest('GET','courier/me')->get_status()===200,'Courier no accesible.');
 wp_set_current_user(0);$providers=dRequest('GET','services')->get_data()['data'];dAssert(count($providers)===6,'Catálogo Prestadores no contiene seis perfiles.');dAssert($providers[0]['featured']===true,'Destacado sin prioridad.');$jose=array_values(array_filter($providers,static fn(array $r):bool=>$r['name']==='José Martínez'))[0]??null;dAssert($jose!==null,'José no visible.');$detail=dRequest('GET','services/'.$jose['id'])->get_data();$json=(string)wp_json_encode($detail);dAssert(str_contains($json,'contact_email')&&!str_contains($json,'rut'),'Contacto/privacidad Prestador inválidos.');
 dAssert((int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}stores WHERE business_name IN ('Minimarket Los Vecinos','Minimarket Central','Minimarket Plaza Sur') AND status='active' AND onboarding_status='complete'")===3,'Admin Stores incompleto.');dAssert((int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}couriers WHERE display_name='Diego Morales' AND status='approved'")===1,'Admin Courier incompleto.');dAssert((int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}service_providers WHERE status='published'")===6,'Admin Prestadores incompleto.');dAssert((int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}products WHERE sku LIKE 'DEMO-%' AND status='active'")===20,'Admin Products incompleto.');
 echo "LOGIN=PASS PANELS=PASS ISOLATION=PASS PROVIDERS=PASS ADMIN=PASS IMAGES=PASS TIMESTAMPS=PASS products=".count($demoProducts)." rows=".count($temporalRows)."\nOFFICIAL_CART=PASS items=".implode(',',$added)."\n";
}finally{wp_set_current_user($customer->ID);dRequest('DELETE','cart');wp_set_current_user(0);}
